const REF_SYMBOL_PATHS=new Map();
function drawReferenceSymbol(ctx,kind,x,y,size,fill){
 const def=REF_SYMBOLS[kind];if(!def)return false;
 let paths=REF_SYMBOL_PATHS.get(kind);if(!paths){paths=def.paths.map(([d,tx,ty])=>({path:new Path2D(d),tx,ty}));REF_SYMBOL_PATHS.set(kind,paths)}
 const scale=size/Math.max(def.width,def.height);ctx.save();ctx.translate(x-def.width*scale/2,y-def.height*scale/2);ctx.scale(scale,scale);ctx.fillStyle=fill;ctx.shadowBlur=0;ctx.shadowColor='transparent';
 for(const p of paths){ctx.save();ctx.translate(p.tx,p.ty);ctx.fill(p.path);ctx.restore()}
 ctx.restore();return true;
}
